function reconcile(p,old) {
const j=(k,which=p)=>JSON.parse(which.files[k].content);
function equal(a,b){return JSON.stringify(a)===JSON.stringify(b)}function assert(ok,name){if(!ok)throw Error(name)}
const e=j("candidate-candidate-only-execution.json"),c=j("candidate-candidate-only-collection.json"),ids=c.comparison.map(r=>r.nodeid);
assert(ids.length===12&&new Set(ids).size===12,"12 unique");
assert(e.actual_cases===12&&e.session_testscollected===12&&e.session_testsfailed===0&&e.exit_code===0&&e.passed&&e.terminal&&e.refused_execution.length===0&&e.errors.length===0,"execution terminal");
assert(equal(e.comparison,c.comparison)&&e.prior_collection_sha256===p.files["candidate-candidate-only-collection.json"].sha256,"prior collection");
assert(e.execution_collection_matches_prior&&e.observed_source_files_unchanged,"execution currentness");
assert(e.body_reports.length===36,"phases");
for(let i=0;i<12;i++)for(let n=0;n<3;n++){const r=e.body_reports[i*3+n];assert(r.nodeid===ids[i]&&r.phase===["setup","call","teardown"][n]&&r.outcome==="passed"&&r.wasxfail===null&&r.longrepr===null,"phase "+i+"/"+n);}
const xml=p.files["candidate-candidate-only-execution.xml"].content;
assert(!/<(?:failure|error|skipped)\b/.test(xml),"xml failures");
const attrs=t=>Object.fromEntries([...t.matchAll(/([a-zA-Z_]+)="([^"]*)"/g)].map(m=>[m[1],m[2].replace(/&quot;/g,'"').replace(/&apos;/g,"'").replace(/&lt;/g,"<").replace(/&gt;/g,">").replace(/&amp;/g,"&")]));
const suite=attrs(xml.match(/<testsuite\s([^>]+)>/)[1]),cases=[...xml.matchAll(/<testcase\s([^>]*?)\s*\/>/g)].map(m=>attrs(m[1]));
assert(suite.tests==="12"&&suite.errors==="0"&&suite.failures==="0"&&suite.skipped==="0"&&cases.length===12,"suite");
for(let i=0;i<12;i++){const [path,name]=ids[i].split("::");assert(cases[i].classname===path.slice(0,-3).replaceAll("/",".")&&cases[i].name===name,"JUnit identity "+i);}
const b17=j("baseline-existing-collection.json"),c17=j("candidate-existing-collection.json"),o17=j("candidate-existing-execution.json",old);
assert(b17.actual_cases===17&&c17.actual_cases===17&&equal(b17.comparison,c17.comparison),"baseline candidate17");
for(const key of ["comparison","raw_origins","source_files","selectors"])assert(equal(c17[key],o17[key]),"old17 "+key);
assert(Object.keys(c17.source_files).length===33&&!Object.keys(c17.source_files).includes("scripts/qualify_guard_package_unversioned_route.py"),"33 sources excluding route");
const before=j("source-before.json"),after=j("source-after.json"),oldBefore=j("source-before.json",old);
assert(equal(before,after)&&equal(j("baseline-before.json"),j("baseline-after.json"))&&equal(j("environment-before.json"),j("environment-after.json")),"before after");
const delta=Object.keys(before.files).filter(k=>!equal(before.files[k],oldBefore.files[k]));
assert(Object.keys(before.files).length===4567&&Object.keys(oldBefore.files).length===4567&&equal(delta,["scripts/qualify_guard_package_unversioned_route.py"]),"whole source delta");
assert(before.files[delta[0]].sha256==="c66363c920ef26588a8499d203390dc8cb0a0af2132be9b00a2cab772b6b8eae","route sha");
const commands=j("commands.json");
assert(commands.length===23&&commands.every(r=>r.passed&&r.returncode===0&&!r.timed_out&&r.group_cleanup.passed&&r.group_cleanup.no_live_members_in_original_group),"23 commands");
assert(commands.filter(r=>r.name.includes("execution")).map(r=>r.name).join()==="candidate-candidate-only-execution","no extra execution");
assert(!commands.some(r=>r.name.includes("corpus")||r.name.includes("metric")),"no corpus metric");
const route=j("package-unversioned-route.json");
assert(route.assertions_passed&&equal(route.source,route.final_source)&&route.source.commit===before.source_sha&&route.source.source_status.length===0,"route currentness");
assert(equal(route.full_evaluator_cases.map(x=>x.case),["bare_registry_direct","lockfile_resolved_direct","exact_transitive"])&&route.full_evaluator_cases.every(x=>x.result.decision==="block"&&x.persisted_evidence.length>0),"three routes");
const proof=j("package-eval-source-contract.json");
assert(proof.passed&&proof.moved_functions===160&&proof.live_global_loads===923&&proof.whole_ordered_original_module_equal&&proof.precise_forward_and_inverse_ast_equal,"source proof");
return {
fresh_cases:{case_count:12,passed_cases:12,failed_cases:0,skipped_cases:0,all_36_ordered_setup_call_teardown_reports_passed:true,ordered_junit_bijection:true,current_execution_collection_equals_prior:true,prior_snapshot_sha256:p.files["candidate-candidate-only-collection.json"].sha256,execution_snapshot_sha256:p.files["candidate-candidate-only-execution.json"].sha256,junit_sha256:p.files["candidate-candidate-only-execution.xml"].sha256,case_ids:ids,raw_phases:e.body_reports},
retained_existing17:{actual_existing_cases:17,no_existing_bodies_executed:true,current_baseline_comparison_equal:true,current_comparison_raw_origins_all_33_sources_selectors_equal_prior:true,old_execution_snapshot_sha256:old.files["candidate-existing-execution.json"].sha256,current_collection_snapshot_sha256:p.files["candidate-existing-collection.json"].sha256,prior_source:"b81da3dd48dd0315bd17a22ce5f1c221c941c0ee",current_source:before.source_sha,full_4567_source_rows_compared:true,only_changed_source:delta},
route:{cases:route.full_evaluator_cases.map(x=>({case:x.case,cached_bundle_calls:x.cached_bundle_calls,decision:x.result.decision,enforcement:x.result.enforcement,persisted_evidence_count:x.persisted_evidence.length})),assertions_passed:true,actual_provider_bindings:route.evaluator_bound_lookup_sources,source_unchanged:true},
environment_source_and_cleanup:{source_before_after_exact:true,baseline_before_after_exact:true,environment_before_after_exact:true,commands:23,all_commands_zero_and_not_timed_out:true,all_original_owned_groups_retired:true,no_complete_descendant_cleanup_certificate:true,no_existing_body_or_corpus_metric_rerun:true}
};
}
